#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int minDistance(const char *word1, const char *word2) {
    int m = (int)strlen(word1);
    int n = (int)strlen(word2);

    if (m < n) {
        const char *tmp = word1;
        word1 = word2;
        word2 = tmp;
        int t = m;
        m = n;
        n = t;
    }

    int *prev = (int *)malloc((n + 1) * sizeof(int));
    int *cur = (int *)malloc((n + 1) * sizeof(int));

    if (prev == NULL || cur == NULL) {
        free(prev);
        free(cur);
        return -1;
    }

    for (int j = 0; j <= n; ++j) {
        prev[j] = j;
    }

    for (int i = 1; i <= m; ++i) {
        cur[0] = i;

        for (int j = 1; j <= n; ++j) {
            int insert_cost = cur[j - 1] + 1;
            int delete_cost = prev[j] + 1;
            int replace_cost = prev[j - 1] + (word1[i - 1] == word2[j - 1] ? 0 : 1);

            int best = insert_cost < delete_cost ? insert_cost : delete_cost;
            if (replace_cost < best) best = replace_cost;

            cur[j] = best;
        }

        int *tmp = prev;
        prev = cur;
        cur = tmp;
    }

    int answer = prev[n];
    free(prev);
    free(cur);
    return answer;
}

static int extract_string(const char *line, int *pos, char *out, int capacity) {
    int len = (int)strlen(line);
    while (*pos < len && line[*pos] != '"') {
        (*pos)++;
    }

    if (*pos >= len) {
        out[0] = '\0';
        return 0;
    }

    (*pos)++;
    int out_pos = 0;

    while (*pos < len && line[*pos] != '"') {
        if (out_pos + 1 < capacity) {
            out[out_pos++] = line[*pos];
        }
        (*pos)++;
    }

    out[out_pos] = '\0';

    if (*pos < len) {
        (*pos)++;
    }

    return 1;
}

int main(void) {
    char line[1300];
    char word1[600];
    char word2[600];

    if (!fgets(line, sizeof(line), stdin)) {
        return 0;
    }

    int pos = 0;

    if (!extract_string(line, &pos, word1, sizeof(word1))) {
        return 0;
    }

    if (!extract_string(line, &pos, word2, sizeof(word2))) {
        word2[0] = '\0';
    }

    printf("%d\n", minDistance(word1, word2));
    return 0;
}

