#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int minDistance(string word1, string word2) {
        if (word1.size() < word2.size()) {
            swap(word1, word2);
        }

        int n = static_cast<int>(word2.size());
        vector<int> prev(n + 1);

        iota(prev.begin(), prev.end(), 0);

        for (int i = 1; i <= static_cast<int>(word1.size()); ++i) {
            vector<int> cur(n + 1);
            cur[0] = i;

            for (int j = 1; j <= n; ++j) {
                int insertCost = cur[j - 1] + 1;
                int deleteCost = prev[j] + 1;
                int replaceCost = prev[j - 1] + (word1[i - 1] == word2[j - 1] ? 0 : 1);
                cur[j] = min(insertCost, min(deleteCost, replaceCost));
            }

            prev.swap(cur);
        }

        return prev[n];
    }
};

static vector<string> parseStrings(const string& line) {
    vector<string> result;

    for (size_t i = 0; i < line.size();) {
        if (line[i] == '"') {
            ++i;
            string value;
            while (i < line.size() && line[i] != '"') {
                value.push_back(line[i++]);
            }
            if (i < line.size()) ++i;
            result.push_back(value);
        } else {
            ++i;
        }
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    if (!getline(cin, line)) return 0;

    vector<string> values = parseStrings(line);
    string word1 = values.size() > 0 ? values[0] : "";
    string word2 = values.size() > 1 ? values[1] : "";

    cout << Solution().minDistance(word1, word2) << '\n';
    return 0;
}

