import java.io.*;
import java.util.*;

class Solution {
    public int minDistance(String word1, String word2) {
        if (word1.length() < word2.length()) {
            String temp = word1;
            word1 = word2;
            word2 = temp;
        }

        int m = word1.length();
        int n = word2.length();
        int[] prev = new int[n + 1];

        for (int j = 0; j <= n; j++) {
            prev[j] = j;
        }

        for (int i = 1; i <= m; i++) {
            int[] cur = new int[n + 1];
            cur[0] = i;

            for (int j = 1; j <= n; j++) {
                int insertCost = cur[j - 1] + 1;
                int deleteCost = prev[j] + 1;
                int replaceCost = prev[j - 1] + (word1.charAt(i - 1) == word2.charAt(j - 1) ? 0 : 1);
                cur[j] = Math.min(insertCost, Math.min(deleteCost, replaceCost));
            }
            prev = cur;
        }

        return prev[n];
    }
}

public class Main {
    private static String[] parseStrings(String line) {
        ArrayList<String> result = new ArrayList<>();
        int i = 0;

        while (i < line.length()) {
            if (line.charAt(i) == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < line.length() && line.charAt(i) != '"') {
                    sb.append(line.charAt(i++));
                }
                if (i < line.length()) i++;
                result.add(sb.toString());
            } else {
                i++;
            }
        }

        return result.toArray(new String[0]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] values = parseStrings(line);

        String word1 = values.length > 0 ? values[0] : "";
        String word2 = values.length > 1 ? values[1] : "";

        System.out.println(new Solution().minDistance(word1, word2));
    }
}

